<?php require 'includes/db.php';require 'includes/auth.php';require_login();$s=db()->prepare('SELECT * FROM orders WHERE user_id=? ORDER BY id DESC');$s->execute([user_id()]);$orders=$s->fetchAll();require 'includes/header.php';?><h1>Your Orders</h1><?php if(isset($_GET['placed'])):?><div class="success">Order placed successfully.</div><?php endif;?><?php if(!$orders):?><div class="notice">No orders yet.</div><?php else:?><div class="grid"><?php foreach($orders as $o):?><article class="card"><h3>Order #<?=$o['id']?></h3><p>Status: <b><?=e($o['status'])?></b></p><p>Total: ₹<?=number_format($o['total'],2)?></p><p class="muted"><?=e($o['created_at'])?></p></article><?php endforeach;?></div><?php endif;require 'includes/footer.php';?>